"""Generate the persisted parliament state machine and public story effects."""
from common import *


def politics(fields, party=None):
    # Runtime set_politics requires the ruling party even for calendar edits.
    def command(p):
        if 'elections_allowed' in fields:return 'set_politics = { ruling_party = '+p+' '+fields+' }\n'
        return iff(ck('elections_enabled','=',1),'set_politics = { ruling_party = '+p+' elections_allowed = yes '+fields+' }\n','set_politics = { ruling_party = '+p+' elections_allowed = no '+fields+' }\n')
    return command(party) if party else ''.join(iff('has_government = '+p,command(p)) for p in PARTIES)


def generate():
    regimes=load_json('regimes.json')
    sources=load_json('attitude_sources.json')['sources']
    opening=load_json('opening_countries.json')
    law_groups=load_json('laws.json')['groups']
    s='# Generated by tools/parliament/build.py. Stable schema 1.\n'
    triggers=block(P+'is_active','has_country_flag = '+P+'initialized')
    triggers+=block(P+'can_submit','has_country_flag = '+P+'initialized '+ck('agenda','=',0))
    # 1-based native sprite frames; variables preserve full integer seats.
    b='clear_array = '+P+'seat_colors\n'
    for i,p in enumerate(PARTIES):
        b+=sv('fill_count',var('seats_'+p))+block('while_loop_effect','limit = { '+ck('fill_count','>',0)+' }\nadd_to_array = { '+P+'seat_colors = '+str(i+1)+' }\n'+op('fill_count','subtract',1))
    s+=effect('rebuild_seat_colors',b+op('dirty','add',1))
    # Per-party corrected Hamilton remainder: numerator - floor * denominator.
    b=sv('weight_total',0)+sv('allocation_ok',0)
    for p in PARTIES:
        b+=sv('weight_'+p,'modifier@'+P+p+'_seat_factor')+op('weight_'+p,'add',1)+clamp('weight_'+p,0,None)
        b+=op('weight_'+p,'multiply','party_popularity@'+p)
        b+=iff('has_country_flag = '+P+'banned_'+p,sv('weight_'+p,0))
        b+=sv('popular_'+p,'party_popularity@'+p)+op('weight_total','add',var('weight_'+p))
    allocate=sv('allocated',0)
    for p in PARTIES:
        allocate+=sv('new_'+p,var('weight_'+p))+op('new_'+p,'multiply',500)+sv('numerator_'+p,var('new_'+p))+op('new_'+p,'divide',var('weight_total'))+floor('new_'+p)
        allocate+=sv('remainder_'+p,var('new_'+p))+op('remainder_'+p,'multiply',var('weight_total'))+op('remainder_'+p,'multiply',-1)+op('remainder_'+p,'add',var('numerator_'+p))+op('allocated','add',var('new_'+p))
    allocate+=sv('unfilled',500)+op('unfilled','subtract',var('allocated'))
    rank=sv('best',0)+sv('best_remainder',-1)+sv('best_support',-1)+sv('tied',0)
    for i,p in enumerate(PARTIES):
        take=sv('best',i+1)+sv('best_remainder',var('remainder_'+p))+sv('best_support',var('popular_'+p))+sv('tied',1)
        tie=op('tied','add',1)+'set_variable_to_random = { var = '+var('draw')+' min = 1 max = '+var('tied')+' integer = yes }\n'+iff(ck('draw','=',1),sv('best',i+1))
        test=ck('remainder_'+p,'>',var('best_remainder'))+' OR = { '+ck('weight_'+p,'>',0)+' }'
        equal=ck('remainder_'+p,'=',var('best_remainder'))+' '+ck('weight_'+p,'>',0)
        rank+=iff(test,take,iff(equal,iff(ck('popular_'+p,'>',var('best_support')),take,iff(ck('popular_'+p,'=',var('best_support')),tie))))
    for i,p in enumerate(PARTIES):
        rank+=iff(ck('best','=',i+1),op('new_'+p,'add',1)+sv('remainder_'+p,-1))
    rank+=op('unfilled','subtract',1)
    allocate+=block('while_loop_effect','limit = { '+ck('unfilled','>',0)+' }\n'+rank)
    allocate+=sv('seat_total',0)+''.join(op('seat_total','add',var('new_'+p)) for p in PARTIES)
    publish=''.join(sv('seats_'+p,var('new_'+p)) for p in PARTIES)+sv('allocation_ok',1)+'clr_country_flag = '+P+'allocation_error\napdc_parl_rebuild_seat_colors = yes\n'
    allocate+=iff(ck('seat_total','=',500),publish,'set_country_flag = '+P+'allocation_error\nlog = "APDC_PARL ERROR seat total [ROOT.GetTag] [?apdc_parl_seat_total]"\n')
    b+=iff(ck('weight_total','>',0),allocate,'set_country_flag = '+P+'allocation_error\nlog = "APDC_PARL ERROR zero legal election weight [ROOT.GetTag]"\n')
    s+=effect('allocate_seats',b)
    # Explicit story grouping: numbers are stable alliance IDs, 0 is solo.
    for p in PARTIES:
        s+=effect('set_'+p+'_electoral_alliance',sv('alliance_'+p,'$ID$'))
        s+=effect('clear_'+p+'_electoral_alliance',sv('alliance_'+p,0))
    b=sv('winner',0)+sv('winner_seats',-1)+sv('winner_ties',0)
    for i,p in enumerate(PARTIES):
        b+=sv('bloc_'+p,var('seats_'+p))
        for j,q in enumerate(PARTIES):
            if p==q:continue
            b+=iff(ck('alliance_'+p,'>',0)+' '+ck('alliance_'+p,'=',var('alliance_'+q)),op('bloc_'+p,'add',var('seats_'+q)))
        first=' '.join('NOT = { AND = { NOT = { has_country_flag = '+P+'banned_'+q+' } '+ck('alliance_'+p,'>',0)+' '+ck('alliance_'+p,'=',var('alliance_'+q))+' } }' for q in PARTIES[:i])
        b+=iff('NOT = { has_country_flag = '+P+'banned_'+p+' } '+first,
               iff(ck('bloc_'+p,'>',var('winner_seats')),sv('winner',i+1)+sv('winner_seats',var('bloc_'+p))+sv('winner_ties',1),iff(ck('bloc_'+p,'=',var('winner_seats')),op('winner_ties','add',1))))
    winners='set_country_flag = '+P+'changing_government\n'
    winners+=''.join('clr_country_flag = APDC_governing_coalition_'+p+'\n'+sv('winner_'+p,0) for p in PARTIES)
    for i,p in enumerate(PARTIES):
        body='set_country_flag = APDC_governing_coalition_'+p+'\n'+sv('winner_'+p,1)
        body+=sv('bloc_leader',i+1)+sv('bloc_leader_seats',var('seats_'+p))+sv('bloc_leader_support','party_popularity@'+p)+sv('bloc_leader_ties',1)
        for q in PARTIES:
            if q!=p:
                take=sv('bloc_leader',PARTIES.index(q)+1)+sv('bloc_leader_seats',var('seats_'+q))+sv('bloc_leader_support','party_popularity@'+q)+sv('bloc_leader_ties',1)
                pick=iff(ck('seats_'+q,'>',var('bloc_leader_seats')),take,iff(ck('seats_'+q,'=',var('bloc_leader_seats')),iff('check_variable = { party_popularity@'+q+' > '+var('bloc_leader_support')+' }',take,iff('check_variable = { party_popularity@'+q+' = '+var('bloc_leader_support')+' }',op('bloc_leader_ties','add',1)+'set_variable_to_random = { var = '+var('draw')+' min = 1 max = '+var('bloc_leader_ties')+' integer = yes }\n'+iff(ck('draw','=',1),sv('bloc_leader',PARTIES.index(q)+1))))))
                body+=iff(ck('alliance_'+p,'>',0)+' '+ck('alliance_'+p,'=',var('alliance_'+q))+' NOT = { has_country_flag = '+P+'banned_'+q+' }','set_country_flag = APDC_governing_coalition_'+q+'\n'+sv('winner_'+q,1)+pick)
        for j,q in enumerate(PARTIES,1):body+=iff(ck('bloc_leader','=',j),politics('',party=q))
        winners+=iff(ck('winner','=',i+1),body)
    winners+='clr_country_flag = '+P+'changing_government\nclr_country_flag = '+P+'election_tied\n'+sv('free_prime',1)+sv('free_deputy',1)+op('term','add',1)
    winners+='apdc_parl_sync_election_interval = yes\nAPDC_update_cabinet_statistics = yes\napdc_parl_reconcile_cabinet = yes\n'
    tie='set_country_flag = '+P+'election_tied\n'+politics('election_frequency = 6')
    s+=effect('resolve_winner',b+iff(ck('winner_ties','=',1),winners,tie))
    s+=effect('run_election',op('election_serial','add',1)+'apdc_parl_allocate_seats = yes\n'+iff(ck('allocation_ok','=',1),'apdc_parl_resolve_winner = yes\napdc_parl_refresh = yes\n'))
    # Native election calendar remains authoritative for anniversaries/releases.
    interval=sv('interval_supported',0)
    periods={6,12,24,36,48,60,72,84,96,108,120,240}
    periods.update(c['elections']['interval_months'] for c in opening.values() if c['elections']['interval_months'])
    periods.update(load_json('settings.json').get('additional_election_intervals',[]))
    for months in sorted(periods):
        interval+=iff(ck('interval_months','=',months),politics('election_frequency = '+str(months))+sv('interval_supported',1))
    interval+=iff(ck('interval_supported','=',0),'log = "APDC_PARL ERROR election interval not in compiled catalogue: [?apdc_parl_interval_months]"\n')
    s+=effect('sync_election_interval',interval)
    s+=effect('set_election_interval',sv('interval_months','$MONTHS$')+iff(ck('interval_months','>',0),politics('elections_allowed = yes')+'apdc_parl_sync_election_interval = yes\n'+sv('elections_enabled',1),politics('elections_allowed = no')+sv('elections_enabled',0))+op('dirty','add',1))
    s+=effect('force_election',sv('before_election',var('election_serial'))+'hold_election = THIS\n'+iff(ck('before_election','=',var('election_serial')),'apdc_parl_run_election = yes\n'))
    # Regime and reform setters are the sole state/idea application boundary.
    b=''
    for i,(key,r) in enumerate(regimes.items(),1):
        b+=iff(ck('regime','=',i),sv('base_days',r['base_days'])+sv('bonus_factor',r['party_bonus_factor'])+sv('opposition_factor',r['opposition_factor']))
    s+=effect('refresh_regime',b)
    # Attitude sources: stable arrays enable arbitrary plot-defined tooltip rows.
    for p in PARTIES:
        known='OR = { '+' '.join(ck('source_token','=', 'token:'+P+'source_'+v['key']) for v in sources)+' }'
        add_source=sv('source_token','token:$NAME$')+iff(known,'add_to_array = { '+P+p+'_source_names = token:$NAME$ }\nadd_to_array = { '+P+p+'_source_values = $VALUE$ }\napdc_parl_refresh = yes\n','log = "APDC_PARL ERROR unknown attitude source: $NAME$; register tools/parliament/data/attitude_sources.json"\n')
        s+=effect('add_'+p+'_attitude_source',add_source)
        set_source=sv('source_token','token:$NAME$')+sv('source_index',0)+sv('source_found',0)
        set_source+=block('while_loop_effect','limit = { '+ck('source_index','<',P+p+'_source_names^num')+' }\n'+iff('check_variable = { '+P+p+'_source_names^'+var('source_index')+' = '+var('source_token')+' }','set_variable = { '+P+p+'_source_values^'+var('source_index')+' = $VALUE$ }\n'+sv('source_found',1))+op('source_index','add',1))
        set_source+=iff(ck('source_found','=',0),P+'add_'+p+'_attitude_source = { NAME = $NAME$ VALUE = $VALUE$ }\n','apdc_parl_refresh = yes\n')
        s+=effect('set_'+p+'_attitude_source',set_source)
        s+=effect('clear_'+p+'_attitude_sources','clear_array = '+P+p+'_source_names\nclear_array = '+P+p+'_source_values\napdc_parl_refresh = yes\n')
        s+=effect('change_'+p+'_bill_attitude',op('bill_attitude_'+p,'add','$VALUE$')+'apdc_parl_refresh = yes\n')
    b='apdc_parl_refresh_regime = yes\n'+sv('support',50)
    for i,p in enumerate(PARTIES):
        for j,q in enumerate(PARTIES):b+=iff('has_government = '+q,sv('base_attitude_'+p,-10*abs(i-j)))
        b+=sv('attitude_'+p,var('base_attitude_'+p))+sv('source_index',0)+''.join(sv('source_tip_'+p+'_'+str(v['id']),0) for v in sources)
        source_rows=''
        for source in sources:
            source_rows+=iff('check_variable = { '+P+p+'_source_names^'+var('source_index')+' = token:'+P+'source_'+source['key']+' }',op('source_tip_'+p+'_'+str(source['id']),'add',P+p+'_source_values^'+var('source_index')))
        b+=block('while_loop_effect','limit = { '+ck('source_index','<',P+p+'_source_values^num')+' }\n'+op('attitude_'+p,'add',P+p+'_source_values^'+var('source_index'))+source_rows+op('source_index','add',1))
        b+=iff('has_country_flag = APDC_governing_coalition_'+p,op('attitude_'+p,'add',100))+clamp('attitude_'+p,-100,100)
        b+=iff('has_government = '+p,sv('attitude_'+p,100))
        b+=sv('bill_support_'+p,var('attitude_'+p))+op('bill_support_'+p,'add',var('bill_attitude_'+p))+clamp('bill_support_'+p,-100,100)
        b+=sv('contribution_'+p,var('seats_'+p))+op('contribution_'+p,'divide',500)+op('contribution_'+p,'multiply',var('bill_support_'+p))+op('contribution_'+p,'multiply',var('opposition_factor'))+op('support','add',var('contribution_'+p))
        b+=sv('bonus_'+p,var('seats_'+p))+op('bonus_'+p,'divide',500)+op('bonus_'+p,'multiply',var('attitude_'+p))+op('bonus_'+p,'divide',100)+op('bonus_'+p,'multiply',var('bonus_factor'))
    b+=sv('support_speed',var('support'))+op('support_speed','subtract',100)+op('support_speed','multiply',0.02)+clamp('support_speed',0,1)+op('support_speed','add',1)
    b+=sv('ordinary_speed','modifier@'+P+'review_speed_factor')+op('ordinary_speed','add',1)+clamp('ordinary_speed',0,None)+op('support_speed','multiply',var('ordinary_speed'))
    rescale=iff(ck('bill_base_days','>',0)+' '+ck('bill_base_days','!=',var('base_days')),op('bill_work','divide',var('bill_base_days'))+op('bill_work','multiply',var('base_days')))+sv('bill_base_days',var('base_days'))
    rescale+=sv('progress',var('bill_work'))+op('progress','divide',var('bill_base_days'))+op('progress','multiply',100)+clamp('progress',0,100)
    b+=iff(ck('agenda','>',0)+' '+ck('base_days','>',0),rescale)
    b+=sv('remaining_days',0)
    remain=sv('remaining_days',var('bill_base_days'))+op('remaining_days','subtract',var('bill_work'))+op('remaining_days','divide',var('support_speed'))
    b+=iff(ck('agenda','>',0)+' '+ck('support_speed','>',0),remain)
    b+=sv('progress_pixels',var('progress'))+op('progress_pixels','multiply',10.06)+floor('progress_pixels')
    for i in range(10):
        width=min(101,1006-i*101)
        b+=sv('progress_frame_'+str(i),var('progress_pixels'))+op('progress_frame_'+str(i),'subtract',i*101)+clamp('progress_frame_'+str(i),0,width)+op('progress_frame_'+str(i),'add',1)
    b+=sv('remaining_display',var('remaining_days'))+floor('remaining_display')+iff(ck('remaining_display','<',var('remaining_days')),op('remaining_display','add',1))
    b+=sv('latch_1',1)+sv('latch_2',1)+iff(ck('stage','>=',2),sv('latch_1',2))+iff(ck('stage','>=',3),sv('latch_2',2))
    # The native date encoding uses 0.00001 per hour (verified in-game).
    b+=sv('next_date','global.date')+sv('election_days','days_until_next_election')+op('election_days','multiply',0.00024)+op('next_date','add',var('election_days'))
    # Match the requested Chinese date, using the same packed native calendar.
    # A native year is 365 days; the encoded epoch includes a 5000-year offset.
    b+=sv('date_year_encoded',var('next_date'))+op('date_year_encoded','divide',0.0876)+floor('date_year_encoded')
    b+=sv('next_year',var('date_year_encoded'))+op('next_year','subtract',5000)
    b+=sv('date_year_start',var('date_year_encoded'))+op('date_year_start','multiply',0.0876)
    b+=sv('date_day_of_year',var('next_date'))+op('date_day_of_year','subtract',var('date_year_start'))+op('date_day_of_year','divide',0.00024)+floor('date_day_of_year')
    for month,day_start in enumerate([0,31,59,90,120,151,181,212,243,273,304,334],1):
        b+=iff(ck('date_day_of_year','>=',day_start),sv('next_month',month)+sv('next_day',var('date_day_of_year'))+op('next_day','subtract',day_start)+op('next_day','add',1))
    b+='force_update_dynamic_modifier = yes\n'+op('dirty','add',1)
    s+=effect('refresh',b)
    # All actions clear only the current agenda; elections never call cleanup.
    cleanup=sv('agenda',0)+sv('stage',0)+sv('progress',0)+sv('bill_work',0)+sv('bill_base_days',0)+sv('bill_kind',0)+sv('bill_target',0)+sv('bill_option',0)
    cleanup+=''.join(sv('bill_attitude_'+p,0) for p in PARTIES)+'apdc_parl_refresh = yes\n'
    s+=effect('finish_agenda',cleanup)
    s+=effect('fail_agenda',sv('last_result',-1)+sv('last_kind',var('bill_kind'))+sv('last_target',var('bill_target'))+iff(ck('bill_kind','=',4),sv('last_failed_special_id',var('bill_target'))+'apdc_parl_special_failed_dispatch = yes\napdc_parl_special_failed_hook = yes\n')+'apdc_parl_finish_agenda = yes\n')
    pass_body=sv('last_result',1)+sv('last_kind',var('bill_kind'))+sv('last_target',var('bill_target'))+sv('trigger_election',0)
    for g in law_groups:
        for o in g['options']:
            pass_body+=iff(ck('bill_kind','=',1)+' '+ck('bill_target','=',g['id'])+' '+ck('bill_option','=',o['id']),P+'enact_'+g['key']+'_'+str(o['id'])+' = yes\n')
    for i,p in enumerate(PARTIES,1):
        legal='NOT = { has_government = '+p+' } NOT = { has_country_flag = APDC_governing_coalition_'+p+' }'
        pass_body+=iff(ck('bill_kind','=',2)+' '+ck('bill_target','=',i),iff(legal,'set_country_flag = '+P+'banned_'+p+'\n'+iff(ck('seats_'+p,'>',0),sv('trigger_election',1)),sv('last_result',-1)))
        pass_body+=iff(ck('bill_kind','=',3)+' '+ck('bill_target','=',i),'clr_country_flag = '+P+'banned_'+p+'\n')
    pass_body+=iff(ck('bill_kind','=',4),'apdc_parl_execute_special_bill = yes\n')
    pass_body+='apdc_parl_finish_agenda = yes\n'+iff(ck('trigger_election','=',1),'apdc_parl_force_election = yes\n')
    s+=effect('pass_agenda',pass_body)
    # Crossing thresholds is checked before and after advancement, including
    # accelerated crossing of several stages within the same day.
    validate=sv('work_tripled',var('bill_work'))+op('work_tripled','multiply',3)+sv('base_doubled',var('bill_base_days'))+op('base_doubled','multiply',2)
    validate+=iff(ck('stage','=',2)+' '+ck('support','<',0),'apdc_parl_fail_agenda = yes\n')
    validate+=iff(ck('stage','=',3)+' '+ck('support','<',50),'apdc_parl_fail_agenda = yes\n')
    validate+=iff(ck('agenda','>',0)+' '+ck('stage','=',1)+' '+ck('work_tripled','>=',var('bill_base_days')),iff(ck('support','>',0),sv('stage',2),'apdc_parl_fail_agenda = yes\n'))
    validate+=iff(ck('agenda','>',0)+' '+ck('stage','=',2)+' '+ck('work_tripled','>=',var('base_doubled')),iff(ck('support','>=',50),sv('stage',3),'apdc_parl_fail_agenda = yes\n'))
    validate+=iff(ck('agenda','>',0)+' '+ck('bill_work','>=',var('bill_base_days')),'apdc_parl_pass_agenda = yes\n')
    s+=effect('validate_agenda',validate)
    submit=sv('agenda',1)+sv('stage',1)+sv('progress',0)+sv('bill_work',0)+sv('bill_base_days',var('base_days'))+sv('bill_kind','$KIND$')+sv('bill_target','$TARGET$')+sv('bill_option','$OPTION$')+'apdc_parl_refresh = yes\n'+iff(ck('base_days','=',0),sv('progress',100)+'apdc_parl_validate_agenda = yes\n')
    s+=effect('submit_agenda',iff(P+'can_submit = yes',submit))
    for i,p in enumerate(PARTIES,1):
        triggers+=block(P+'can_ban_'+p,'NOT = { has_government = '+p+' } NOT = { has_country_flag = APDC_governing_coalition_'+p+' } NOT = { has_country_flag = '+P+'banned_'+p+' } '+P+'can_submit = yes')
        s+=effect('submit_ban_'+p,iff(P+'can_ban_'+p+' = yes',P+'submit_agenda = { KIND = 2 TARGET = '+str(i)+' OPTION = 0 }\n'))
        s+=effect('submit_unban_'+p,iff(P+'can_submit = yes has_country_flag = '+P+'banned_'+p,P+'submit_agenda = { KIND = 3 TARGET = '+str(i)+' OPTION = 0 }\n'))
    # Per-country defaults run once from normal history, or as old-save/release
    # fallback. They never replace country histories or country identities.
    defaults=''
    reg_ids={k:i for i,k in enumerate(regimes,1)}
    eco_names=list(json.loads(read('docs/parliament/20261107-design/opening_policy.json'))['economic_names'].values())
    for tag,c in opening.items():
        body=sv('regime',reg_ids[c['political_system']])+sv('interval_months',c['elections']['interval_months'] or 24)+sv('elections_enabled',int(c['elections']['enabled']))
        for g in law_groups:
            if g['id']<5:oid=next(o['id'] for o in g['options'] if o['name']==c['reforms'][g['key']])
            elif g['id']==5:oid=eco_names.index(c['economic_system_name'])+1
            else:oid=reg_ids[c['political_system']]
            body+=P+'enact_'+g['key']+'_'+str(oid)+' = yes\n'
        body+='apdc_parl_refresh_regime = yes\n'
        s+=effect('opening_'+tag,body)
        defaults+=iff('original_tag = '+tag,P+'opening_'+tag+' = yes\n')
    init=iff('NOT = { has_country_flag = '+P+'initialized }','set_country_flag = '+P+'initializing\n'+sv('agenda',0)+sv('stage',0)+sv('progress',0)+sv('term',0)+sv('free_prime',0)+sv('free_deputy',0)+sv('dirty',1)+sv('regime',4)+sv('interval_months',24)+sv('elections_enabled',1)+defaults+
        'set_country_flag = '+P+'initialized\nadd_dynamic_modifier = { modifier = '+P+'party_bonuses }\napdc_parl_initialize_ui_arrays = yes\napdc_parl_migrate_role_records = yes\napdc_parl_allocate_seats = yes\n'+''.join(iff('has_country_flag = APDC_governing_coalition_'+p,sv('winner_'+p,1)) for p in PARTIES)+'apdc_parl_refresh = yes\n'+iff('NOT = { has_global_flag = apdc_parl_bootstrapping }','hold_election = THIS\n')+'clr_country_flag = '+P+'initializing\n')
    s+=effect('initialize',init)
    daily='apdc_parl_initialize = yes\napdc_parl_refresh_special_catalogue = yes\napdc_parl_refresh = yes\napdc_parl_validate_agenda = yes\n'
    advance=op('bill_work','add',var('support_speed'))+clamp('bill_work',0,var('bill_base_days'))+'apdc_parl_refresh = yes\napdc_parl_validate_agenda = yes\napdc_parl_refresh = yes\n'
    daily+=iff(ck('agenda','>',0)+' '+ck('base_days','>',0)+' '+ck('support_speed','>',0),advance)
    s+=effect('daily',daily)
    write('common/scripted_effects/apdc_parliament_backend.txt',s)
    write('common/scripted_triggers/apdc_parliament_triggers.txt',triggers)
    mods=''
    for p in PARTIES:mods+=block(P+p+'_seat_factor','color_type = good\nvalue_type = percentage\nprecision = 2\ncategory = country')
    mods+=block(P+'review_speed_factor','color_type = good\nvalue_type = percentage\nprecision = 2\ncategory = country')
    write('common/modifier_definitions/apdc_parliament_modifiers.txt',mods)
    native=['production_speed_buildings_factor','industrial_capacity_factory','monthly_population','APDC_eco_population_factor','stability_factor','political_power_factor',P+'review_speed_factor','war_support_factor','conscription_factor']
    scales=[1,1,1,-0.5,0.5,1,-0.5,0.5,1]
    dynamic='enable = { has_country_flag = '+P+'initialized }\n'
    # Pre-scaled variables avoid illegal arithmetic inside modifier definitions.
    for p,key,scale in zip(PARTIES,native,scales):
        dynamic+=key+' = '+var('effective_'+p)+'\n'
    write('common/dynamic_modifiers/apdc_parliament_dynamic_modifiers.txt',block(P+'party_bonuses',dynamic))
    # Add scaling immediately before modifier refresh, not after cached reading.
    scales_body=''.join(sv('effective_'+p,var('bonus_'+p))+op('effective_'+p,'multiply',scale) for p,scale in zip(PARTIES,scales))
    path='common/scripted_effects/apdc_parliament_backend.txt'
    text=read(path).replace('force_update_dynamic_modifier = yes\n'+op('dirty','add',1),op('dirty','add',1))
    text=text.replace(sv('ordinary_speed','modifier@'+P+'review_speed_factor'),scales_body+'force_update_dynamic_modifier = yes\n'+sv('ordinary_speed','modifier@'+P+'review_speed_factor'))
    write(path,text)
    on='on_startup = { effect = { set_global_flag = apdc_parl_bootstrapping every_country = { apdc_parl_initialize = yes apdc_parl_refresh_special_catalogue = yes } clr_global_flag = apdc_parl_bootstrapping set_global_flag = apdc_parl_bootstrapped } }\n'
    on+='on_daily = { effect = { if = { limit = { NOT = { has_global_flag = apdc_parl_daily_lock } } set_global_flag = { flag = apdc_parl_daily_lock value = 1 days = 1 } every_country = { apdc_parl_daily = yes } } } }\n'
    on+='on_new_term_election = { effect = { if = { limit = { has_country_flag = apdc_parl_initialized NOT = { has_country_flag = apdc_parl_initializing } } apdc_parl_run_election = yes } } }\n'
    on+='on_release_as_puppet = { effect = { apdc_parl_initialize = yes } }\n'
    on+='on_state_control_changed = { effect = { if = { limit = { has_global_flag = apdc_parl_bootstrapped NOT = { has_country_flag = apdc_parl_initialized } } apdc_parl_initialize = yes } } }\n'
    on+='on_ruling_party_change = { effect = { if = { limit = { has_country_flag = apdc_parl_initialized NOT = { has_country_flag = apdc_parl_changing_government } } apdc_parl_refresh = yes } } }\n'
    write('common/on_actions/zzzz_apdc_parliament.txt',block('on_actions',on))
